<?php
require 'includes/functions.php';$title='Boutique';$base='';$cats=$pdo->query("SELECT * FROM categories ORDER BY name")->fetchAll();
$where=["p.status='active'"];$args=[];if(!empty($_GET['category'])&&ctype_digit((string)$_GET['category'])){$where[]='p.category_id=?';$args[]=(int)$_GET['category'];}
if(!empty($_GET['q'])){$where[]='(p.name LIKE ? OR p.brand LIKE ?)';$q='%'.trim($_GET['q']).'%';$args[]=$q;$args[]=$q;}
if(isset($_GET['max'])&&is_numeric($_GET['max'])){$where[]='p.price<=?';$args[]=(float)$_GET['max'];}
$sort=($_GET['sort']??'')==='asc'?'p.price ASC':(($_GET['sort']??'')==='desc'?'p.price DESC':'p.id DESC');
$s=$pdo->prepare("SELECT p.*,c.name category_name,(SELECT image_path FROM product_images WHERE product_id=p.id ORDER BY is_main DESC,id LIMIT 1) image_path FROM products p JOIN categories c ON c.id=p.category_id WHERE ".implode(' AND ',$where)." ORDER BY $sort");$s->execute($args);$products=$s->fetchAll();require 'includes/header.php';?>
<section class="banner"><div class="container"><small>FOOTZONE STORE</small><h1>LA BOUTIQUE</h1><p>Tous les essentiels du foot au même endroit.</p></div></section><section class="container section">
<form class="filters"><input name="q" placeholder="Rechercher..." value="<?=e($_GET['q']??'')?>"><select name="category"><option value="">Toutes catégories</option><?php foreach($cats as $c):?><option value="<?=(int)$c['id']?>" <?=($_GET['category']??'')==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach?></select><input name="max" type="number" min="0" step=".001" placeholder="Prix max TND" value="<?=e($_GET['max']??'')?>"><select name="sort"><option value="">Plus récents</option><option value="asc" <?=($_GET['sort']??'')==='asc'?'selected':''?>>Prix croissant</option><option value="desc" <?=($_GET['sort']??'')==='desc'?'selected':''?>>Prix décroissant</option></select><button class="btn">Filtrer</button></form>
<p class="muted"><?=count($products)?> produit(s)</p><div class="products lightproducts"><?php foreach($products as $p):?><article class="card"><a href="product.php?id=<?=(int)$p['id']?>"><img src="<?=e(img($p))?>" alt="<?=e($p['name'])?>"></a><div><small><?=e($p['category_name'])?> · <?=e($p['brand'])?></small><h3><a href="product.php?id=<?=(int)$p['id']?>"><?=e($p['name'])?></a></h3><b><?=money($p['price'])?></b></div></article><?php endforeach?></div><?php if(!$products):?><p class="empty">Aucun produit trouvé. <a href="shop.php">Réinitialiser</a></p><?php endif?></section>
